<?php
namespace App\Http\Controllers;
use App\Http\Requests\{LoginRequest,RegisterRequest}; use App\Models\User; use Illuminate\Http\RedirectResponse; use Illuminate\Support\Facades\{Auth,DB}; use Illuminate\Support\Str; use Illuminate\View\View;
class AuthController extends Controller { public function login():View{return view('auth.login');} public function authenticate(LoginRequest $request):RedirectResponse{if(!Auth::attempt($request->safe()->only(['email','password']),$request->boolean('remember')))return back()->withErrors(['email'=>'Email atau password tidak sesuai.'])->onlyInput('email');$request->session()->regenerate();return redirect()->intended(route('dashboard'));} public function register():View{return view('auth.register');} public function store(RegisterRequest $request):RedirectResponse{$user=DB::transaction(function()use($request){$data=$request->validated();$user=User::create(['name'=>$data['name'],'email'=>$data['email'],'phone'=>$data['phone'],'password'=>$data['password']]);$user->assignRole($data['role']);$user->wallet()->create();if($data['role']==='worker')$user->worker()->create(['city'=>$data['city'],'headline'=>'Casual Worker','verification_status'=>'pending']);else $user->company()->create(['name'=>$data['company_name'],'slug'=>Str::slug($data['company_name']).'-'.Str::lower(Str::random(5)),'city'=>$data['city']]);return $user;});Auth::login($user);return redirect()->route('dashboard')->with('success','Akun berhasil dibuat.');} public function logout():RedirectResponse{Auth::logout();request()->session()->invalidate();request()->session()->regenerateToken();return redirect()->route('home');} }
